#!/bin/bash
# test-meta: arch=none needs= est=3 local-only=0
# test-tool-docs-gate.sh -- check-tool-docs.py's README-generator check must
# be able to FAIL.
#
# WHY THIS EXISTS. The tarball's README.txt is generated by
# make-uefi-tools-readme.py, and check-tool-docs.py asserts the staging
# (packaging/uefi-tools/CMakeLists.txt's install rules) still calls it rather than growing a
# hand-written list back. That check was a substring test over the whole file,
# and the script's own comments name the generator -- so with the CALL removed
# the gate stayed green. A detector satisfied by its own rationale; the same
# trap test-tools-sidecars-gate.sh records for the sidecar glob.
#
# Host-only, on a COPY of what the gate reads: never a tracked file.
#
# Usage: ./test/integration/test-tool-docs-gate.sh

set -uo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_DIR="$(dirname "$(dirname "$SCRIPT_DIR")")"

WORK="$(mktemp -d -t axl-tooldocsgate.XXXXXXXX)"; trap 'rm -rf "$WORK"' EXIT
PASS=0; FAIL=0
pass() { echo "  PASS: $1"; PASS=$((PASS + 1)); }
fail() { echo "  FAIL: $1"; FAIL=$((FAIL + 1)); }
indent() { while IFS= read -r l; do echo "      $l"; done; }

# What the gate reads: the tool lists (scripts/axl-list.sh over
# axl-lists.conf), README.md and the staging script.
build_tree() {
    local dst="$1"
    mkdir -p "$dst/scripts" "$dst/packaging/uefi-tools"
    cp "$PROJECT_DIR/README.md" "$PROJECT_DIR/VERSION" "$dst/"
    cp "$PROJECT_DIR/scripts/check-tool-docs.py" \
       "$PROJECT_DIR/scripts/axl-list.sh" "$PROJECT_DIR/scripts/axl-lists.conf" \
       "$dst/scripts/"
    cp "$PROJECT_DIR/packaging/uefi-tools/CMakeLists.txt" "$dst/packaging/uefi-tools/"
}
run_gate() { (cd "$1" && python3 scripts/check-tool-docs.py 2>&1); }

echo "=== 1. baseline: the gate passes on an unmodified tree ==="
BASE="$WORK/base"; build_tree "$BASE"
if out="$(run_gate "$BASE")"; then
    pass "clean tree passes"
else
    fail "clean tree FAILED -- the negative below is meaningless"
    indent <<<"$out" | head -6
fi

echo "=== 2. the call removed, the comment naming the generator kept ==="
T2="$WORK/nocall"; build_tree "$T2"
STAGER="$T2/packaging/uefi-tools/CMakeLists.txt"
# The execute_process runs `cmake -E true` instead -- still valid CMake.
sed -i 's|COMMAND \\"\${Python3_EXECUTABLE}\\" \\"\${AXL_ROOT}/scripts/make-uefi-tools-readme\.py\\"|COMMAND \\"\${CMAKE_COMMAND}\\" -E true|' "$STAGER"
if grep -q '^ *COMMAND .*/scripts/make-uefi-tools-readme\.py' "$STAGER"; then
    fail "fixture did NOT apply -- the call is still there, case 2 proves nothing"
else
    pass "fixture applied: the call is gone"
fi
if grep -q '^ *#.*make-uefi-tools-readme\.py' "$STAGER"; then
    pass "fixture intact: a comment still names make-uefi-tools-readme.py"
else
    fail "no comment names the generator -- case 2 is not the regression"
fi
N=$("$PROJECT_DIR/scripts/axl-list.sh" TOOL_NAMES TOOL_EXTRA_APPS \
    | tr ' ' '\n' | grep -v '^$' | sort -u | wc -l)
WANT="check-tool-docs: packaging/uefi-tools/CMakeLists.txt no longer calls make-uefi-tools-readme.py -- the tarball's README is back to a hand-written list, which is how it came to name 13 of $N tools"
if out="$(run_gate "$T2")"; then
    fail "the call removed passed, because a COMMENT named the generator"
elif grep -qxF -- "$WANT" <<<"$out"; then
    pass "the call removed FAILS the gate with the exact message"
else
    fail "gate failed but not with the exact message"
    indent <<<"$out" | head -4
fi

echo ""
echo "tool-docs-gate: $PASS passed, $FAIL failed"
[[ "$FAIL" -eq 0 ]]
